document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" href="tablet.css">');
const matches=[
 {time:'18:40',a:'Truls Möregårdh',af:'🇸🇪',b:'Lin Shidong',bf:'🇨🇳'}
];
const root=document.querySelector('#tt-matches');root.innerHTML=matches.map((m,i)=>`<article class="tt-match"><time>${m.time}</time><div class="tt-player"><span>${m.af}</span><div><b>${m.a}</b><small>Sverige</small></div></div><strong class="tt-vs">MOT</strong><div class="tt-player right"><div><b>${m.b}</b><small>Kina</small></div><span>${m.bf}</span></div><button type="button" data-i="${i}">Matchfakta +</button><div class="tt-details" id="detail-${i}"><p><b>WTT Champions Montpellier</b><span>Kvartsfinal i Sud de France Arena. Sändningen börjar 18.40 på SVT Play.</span></p><div><a href="https://www.svtplay.se/bordtennis-wtt" target="_blank" rel="noreferrer">Öppna SVT Play ↗</a><br><a href="https://www.worldtabletennis.com/eventslist" target="_blank" rel="noreferrer">WTT:s tävlingscenter ↗</a></div></div></article>`).join('');root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=document.querySelector(`#detail-${b.dataset.i}`),open=d.classList.toggle('open');b.textContent=open?'Stäng −':'Matchfakta +'});
